import{_ as t,o as e,c as d,a2 as o}from"./chunks/framework.BzGQ_3Jc.js";const b=JSON.parse('{"title":"01 后台配置","description":"","frontmatter":{},"headers":[],"relativePath":"01_后台配置.md","filePath":"01_后台配置.md","lastUpdated":1787829343000}'),r={name:"01_后台配置.md"};function l(i,a,h,n,c,s){return e(),d("div",null,[...a[0]||(a[0]=[o('<h1 id="_01-后台配置" tabindex="-1">01 后台配置 <a class="header-anchor" href="#_01-后台配置" aria-label="Permalink to &quot;01 后台配置&quot;">​</a></h1><blockquote><p>文档版本：1.1.5</p></blockquote><p>本篇只讲后台。SDK 怎么 Load / Show 见后面各格式篇。</p><hr><h2 id="_1-获取账号与应用" tabindex="-1">1. 获取账号与应用 <a class="header-anchor" href="#_1-获取账号与应用" aria-label="Permalink to &quot;1. 获取账号与应用&quot;">​</a></h2><h3 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h3><ol><li>联系 TD 运营开通后台账号，登录后进入【应用管理】。</li><li>点击【添加应用】，填写：</li></ol><table tabindex="0"><thead><tr><th>应用信息</th><th>填写说明</th></tr></thead><tbody><tr><td>平台</td><td>Android 或 iOS。一个应用对应一个平台。</td></tr><tr><td>包名 / Bundle ID</td><td>与实际上架包名一致，例如 <code>com.example.app</code>。</td></tr><tr><td>应用名称</td><td>应用真实名称。</td></tr><tr><td>一级 / 二级分类</td><td>游戏选【游戏】，其余选【应用】。</td></tr></tbody></table><ol start="3"><li>保存后得到 <strong>App ID</strong>。初始化 SDK 时传入该 ID（代码里写成您自己的，不要写 Demo 数字）。</li></ol><h3 id="预期结果" tabindex="-1">预期结果 <a class="header-anchor" href="#预期结果" aria-label="Permalink to &quot;预期结果&quot;">​</a></h3><p>【应用管理】列表能看到新建应用，并能复制 App ID。</p><hr><h2 id="_2-添加广告位" tabindex="-1">2. 添加广告位 <a class="header-anchor" href="#_2-添加广告位" aria-label="Permalink to &quot;2. 添加广告位&quot;">​</a></h2><h3 id="操作-1" tabindex="-1">操作 <a class="header-anchor" href="#操作-1" aria-label="Permalink to &quot;操作&quot;">​</a></h3><ol><li>选中应用，点击【添加广告位】。</li><li>按场景选类型。当前支持 5 类：激励、插屏、横幅、原生、开屏。</li><li>保存后得到 <strong>广告位 ID</strong>（长整型）。类型建错会导致无法展示，例如用原生位去请求激励。</li></ol><table tabindex="0"><thead><tr><th>类型</th><th>后台填写说明</th></tr></thead><tbody><tr><td>激励视频</td><td>名称必填。并行请求数初次可保持默认。奖励项目/数量可选，发奖以代码 <code>onAdReward</code> 为准。</td></tr><tr><td>插屏</td><td>名称必填。并行请求数初次可保持默认。</td></tr><tr><td>横幅</td><td>名称必填。若后台开自动刷新，请关闭三方后台的自动刷新，避免双边刷新。</td></tr><tr><td>原生</td><td>名称必填。在后台为该源选择<strong>模板</strong>或<strong>自渲染</strong>（须与三方广告位类型一致）。客户端看 Load 回调里的 <code>renderType</code>，见 <a href="./09_原生广告">09 原生广告</a>。</td></tr><tr><td>开屏</td><td>名称必填。倒计时由广告平台控制。请在 <code>onAdClosed</code> 后进入首页。</td></tr></tbody></table><h3 id="预期结果-1" tabindex="-1">预期结果 <a class="header-anchor" href="#预期结果-1" aria-label="Permalink to &quot;预期结果&quot;">​</a></h3><p>广告位列表可见新建位，并能复制广告位 ID。</p><hr><h2 id="_3-添加广告源、配置瀑布流" tabindex="-1">3. 添加广告源、配置瀑布流 <a class="header-anchor" href="#_3-添加广告源、配置瀑布流" aria-label="Permalink to &quot;3. 添加广告源、配置瀑布流&quot;">​</a></h2><h3 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h3><ol><li>确定要接的广告平台与广告类型（如 JinDai 激励、LiteMob 开屏）。</li><li>在各广告平台创建应用与广告位，拿到该平台要求的应用 ID、广告位 ID 等参数。填写时与三方后台逐项核对。</li></ol><h3 id="操作-2" tabindex="-1">操作 <a class="header-anchor" href="#操作-2" aria-label="Permalink to &quot;操作&quot;">​</a></h3><ol><li>在广告位下【添加广告源】，按后台表单填写三方参数。</li><li>保存后，为该广告位配置瀑布流。</li><li>工程里只加后台实际用到的平台依赖，见 <a href="./02_Android集成">02</a> / <a href="./03_iOS集成">03</a>。</li></ol><h3 id="预期结果-2" tabindex="-1">预期结果 <a class="header-anchor" href="#预期结果-2" aria-label="Permalink to &quot;预期结果&quot;">​</a></h3><p>该广告位下能看到已添加的广告源。客户端 <code>loadAd</code> 后：有填充走 <code>onAdLoaded</code>，无填充走 <code>onAdLoadFailed</code>。展示前用 <code>isReady</code> 判断。</p><hr><h2 id="_4-报表与测试位" tabindex="-1">4. 报表与测试位 <a class="header-anchor" href="#_4-报表与测试位" aria-label="Permalink to &quot;4. 报表与测试位&quot;">​</a></h2><ul><li>需要拉取三方报表时，按后台【广告平台】授权（向运营确认各平台要填的 Key）。</li><li>联调用的测试广告位由运营提供，或使用示例工程自带配置（仅 Demo，见 <a href="./12_测试验收">12 测试验收</a>）。</li></ul><hr>',30)])])}const u=t(r,[["render",l]]);export{b as __pageData,u as default};
